907	      const result = new StreamedRunResult<TContext, TAgent>({
908	        signal: options.signal,
909	        state,
910	      });
911	
912	      // Setup defaults
913	      result.maxTurns = options.maxTurns ?? state._maxTurns;
914	
915	      // Continue the stream loop without blocking
916	      this.#runStreamLoop(result, options).then(
917	        () => {
918	          result._done();
919	        },
920	        (err) => {
921	          result._raiseError(err);
922	        },
923	      );
924	
925	      return result;
926	    });
927	  }
