929	  /**
930	   * Run a workflow starting at the given agent. The agent will run in a loop until a final
931	   * output is generated. The loop runs like so:
932	   * 1. The agent is invoked with the given input.
933	   * 2. If there is a final output (i.e. the agent produces something of type
934	   *    `agent.outputType`, the loop terminates.
935	   * 3. If there's a handoff, we run the loop again, with the new agent.
936	   * 4. Else, we run tool calls (if any), and re-run the loop.
937	   *
938	   * In two cases, the agent may raise an exception:
939	   * 1. If the maxTurns is exceeded, a MaxTurnsExceeded exception is raised.
940	   * 2. If a guardrail tripwire is triggered, a GuardrailTripwireTriggered exception is raised.
941	   *
942	   * Note that only the first agent's input guardrails are run.
943	   *
944	   * @param agent - The starting agent to run.
945	   * @param input - The initial input to the agent. You can pass a string or an array of
946	   * `AgentInputItem`.
947	   * @param options - The options for the run.
948	   * @param options.stream - Whether to stream the run. If true, the run will emit events as the
949	   * model responds.
950	   * @param options.context - The context to run the agent with.
951	   * @param options.maxTurns - The maximum number of turns to run the agent.
952	   * @returns The result of the run.
953	   */
954	  run<TAgent extends Agent<any, any>, TContext = undefined>(
955	    agent: TAgent,
956	    input: string | AgentInputItem[] | RunState<TContext, TAgent>,
957	    options?: NonStreamRunOptions<TContext>,
958	  ): Promise<RunResult<TContext, TAgent>>;
959	  run<TAgent extends Agent<any, any>, TContext = undefined>(
960	    agent: TAgent,
961	    input: string | AgentInputItem[] | RunState<TContext, TAgent>,
962	    options?: StreamRunOptions<TContext>,
963	  ): Promise<StreamedRunResult<TContext, TAgent>>;
964	  run<TAgent extends Agent<any, any>, TContext = undefined>(
965	    agent: TAgent,
966	    input: string | AgentInputItem[] | RunState<TContext, TAgent>,
967	    options: IndividualRunOptions<TContext> = {
968	      stream: false,
969	      context: undefined,
970	    } as IndividualRunOptions<TContext>,
971	  ): Promise<
972	    RunResult<TContext, TAgent> | StreamedRunResult<TContext, TAgent>
973	  > {
974	    if (input instanceof RunState && input._trace) {
975	      return withTrace(input._trace, async () => {
976	        if (input._currentAgentSpan) {
977	          setCurrentSpan(input._currentAgentSpan);
978	        }
979	
980	        if (options?.stream) {
981	          return this.#runIndividualStream(agent, input, options);
982	        } else {
983	          return this.#runIndividualNonStream(agent, input, options);
984	        }
985	      });
986	    }
987	
988	    return getOrCreateTrace(
989	      async () => {
990	        if (options?.stream) {
991	          return this.#runIndividualStream(agent, input, options);
992	        } else {
993	          return this.#runIndividualNonStream(agent, input, options);
994	        }
995	      },
996	      {
997	        traceId: this.config.traceId,
998	        name: this.config.workflowName,
999	        groupId: this.config.groupId,
1000	        metadata: this.config.traceMetadata,
1001	      },
1002	    );
1003	  }
1004	}
