1006	let _defaultRunner: Runner | undefined = undefined;
1007	function getDefaultRunner() {
1008	  if (_defaultRunner) {
1009	    return _defaultRunner;
1010	  }
1011	  _defaultRunner = new Runner();
1012	  return _defaultRunner;
1013	}
