1015	export function selectModel(
1016	  agentModel: string | Model,
1017	  runConfigModel: string | Model | undefined,
1018	): string | Model {
1019	  // When initializing an agent without model name, the model property is set to an empty string. So,
1020	  // * agentModel === '' & runConfigModel exists, runConfigModel will be used
1021	  // * agentModel is set, the agentModel will be used over runConfigModel
1022	  if (
1023	    (typeof agentModel === 'string' &&
1024	      agentModel !== Agent.DEFAULT_MODEL_PLACEHOLDER) ||
1025	    agentModel // any truthy value
1026	  ) {
1027	    return agentModel;
1028	  }
1029	  return runConfigModel ?? agentModel ?? Agent.DEFAULT_MODEL_PLACEHOLDER;
1030	}
