1045	  options?: StreamRunOptions<TContext> | NonStreamRunOptions<TContext>,
1046	): Promise<RunResult<TContext, TAgent> | StreamedRunResult<TContext, TAgent>> {
1047	  const runner = getDefaultRunner();
1048	  if (options?.stream) {
1049	    return await runner.run(agent, input, options);
1050	  } else {
1051	    return await runner.run(agent, input, options);
