1055	/**
1056	 * When the default model is a GPT-5 variant, agents may carry GPT-5-specific providerData
1057	 * (e.g., reasoning effort, text verbosity). If a run resolves to a non-GPT-5 model and the
1058	 * agent relied on the default model (i.e., no explicit model set), these GPT-5-only settings
1059	 * are incompatible and should be stripped to avoid runtime errors.
1060	 */
1061	function adjustModelSettingsForNonGPT5RunnerModel(
1062	  explictlyModelSet: boolean,
1063	  agentModelSettings: ModelSettings,
1064	  runnerModel: string | Model,
1065	  modelSettings: ModelSettings,
1066	): ModelSettings {
1067	  if (
1068	    // gpt-5 is enabled for the default model for agents
1069	    isGpt5Default() &&
1070	    // explicitly set model for the agent
1071	    explictlyModelSet &&
1072	    // this runner uses a non-gpt-5 model
1073	    (typeof runnerModel !== 'string' ||
1074	      !gpt5ReasoningSettingsRequired(runnerModel)) &&
1075	    (agentModelSettings.providerData?.reasoning ||
1076	      agentModelSettings.providerData?.text?.verbosity ||
1077	      (agentModelSettings.providerData as any)?.reasoning_effort)
1078	  ) {
1079	    // the incompatible parameters should be removed to avoid runtime errors
1080	    delete modelSettings.providerData?.reasoning;
1081	    delete (modelSettings.providerData as any)?.text?.verbosity;
1082	    delete (modelSettings.providerData as any)?.reasoning_effort;
1083	  }
1084	  return modelSettings;
1085	}
