237	/**
238	 * Serializable snapshot of an agent's run, including context, usage and trace.
239	 * While this class has publicly writable properties (prefixed with `_`), they are not meant to be
240	 * used directly. To read these properties, use the `RunResult` instead.
241	 *
242	 * Manipulation of the state directly can lead to unexpected behavior and should be avoided.
243	 * Instead, use the `approve` and `reject` methods to interact with the state.
244	 */
245	export class RunState<TContext, TAgent extends Agent<any, any>> {
246	  /**
247	   * Current turn number in the conversation.
248	   */
249	  public _currentTurn = 0;
250	  /**
251	   * The agent currently handling the conversation.
252	   */
253	  public _currentAgent: TAgent;
254	  /**
255	   * Original user input prior to any processing.
256	   */
257	  public _originalInput: string | AgentInputItem[];
258	  /**
259	   * Responses from the model so far.
260	   */
261	  public _modelResponses: ModelResponse[];
262	  /**
263	   * Active tracing span for the current agent if tracing is enabled.
264	   */
265	  public _currentAgentSpan: Span<AgentSpanData> | undefined;
266	  /**
267	   * Run context tracking approvals, usage, and other metadata.
268	   */
269	  public _context: RunContext<TContext>;
270	  /**
271	   * Tracks what tools each agent has used.
272	   */
273	  public _toolUseTracker: AgentToolUseTracker;
274	  /**
275	   * Items generated by the agent during the run.
276	   */
277	  public _generatedItems: RunItem[];
278	  /**
279	   * Maximum allowed turns before forcing termination.
280	   */
281	  public _maxTurns: number;
282	  /**
283	   * Whether the run has an active agent step in progress.
284	   */
285	  public _noActiveAgentRun = true;
286	  /**
287	   * Last model response for the previous turn.
288	   */
289	  public _lastTurnResponse: ModelResponse | undefined;
290	  /**
291	   * Results from input guardrails applied to the run.
292	   */
293	  public _inputGuardrailResults: InputGuardrailResult[];
294	  /**
295	   * Results from output guardrails applied to the run.
296	   */
297	  public _outputGuardrailResults: OutputGuardrailResult[];
298	  /**
299	   * Next step computed for the agent to take.
300	   */
301	  public _currentStep: NextStep | undefined = undefined;
302	  /**
303	   * Parsed model response after applying guardrails and tools.
304	   */
305	  public _lastProcessedResponse: ProcessedResponse<TContext> | undefined =
306	    undefined;
307	  /**
308	   * Trace associated with this run if tracing is enabled.
309	   */
310	  public _trace: Trace | null = null;
311	
312	  constructor(
313	    context: RunContext<TContext>,
314	    originalInput: string | AgentInputItem[],
315	    startingAgent: TAgent,
316	    maxTurns: number,
317	  ) {
318	    this._context = context;
319	    this._originalInput = structuredClone(originalInput);
320	    this._modelResponses = [];
321	    this._currentAgentSpan = undefined;
322	    this._currentAgent = startingAgent;
323	    this._toolUseTracker = new AgentToolUseTracker();
324	    this._generatedItems = [];
325	    this._maxTurns = maxTurns;
326	    this._inputGuardrailResults = [];
327	    this._outputGuardrailResults = [];
328	    this._trace = getCurrentTrace();
329	  }
330	
331	  /**
332	   * The history of the agent run. This includes the input items and the new items generated during the run.
333	   *
334	   * This can be used as inputs for the next agent run.
335	   */
336	  get history(): AgentInputItem[] {
337	    return getTurnInput(this._originalInput, this._generatedItems);
338	  }
339	
340	  /**
341	   * Returns all interruptions if the current step is an interruption otherwise returns an empty array.
342	   */
343	  getInterruptions() {
344	    if (this._currentStep?.type !== 'next_step_interruption') {
345	      return [];
346	    }
347	    return this._currentStep.data.interruptions;
348	  }
