350	  /**
351	   * Approves a tool call requested by the agent through an interruption and approval item request.
352	   *
353	   * To approve the request use this method and then run the agent again with the same state object
354	   * to continue the execution.
355	   *
356	   * By default it will only approve the current tool call. To allow the tool to be used multiple
357	   * times throughout the run, set the `alwaysApprove` option to `true`.
358	   *
359	   * @param approvalItem - The tool call approval item to approve.
360	   * @param options - Options for the approval.
361	   */
362	  approve(
363	    approvalItem: RunToolApprovalItem,
364	    options: { alwaysApprove?: boolean } = { alwaysApprove: false },
365	  ) {
366	    this._context.approveTool(approvalItem, options);
367	  }
