376	   * times throughout the run, set the `alwaysReject` option to `true`.
377	   *
378	   * @param approvalItem - The tool call approval item to reject.
379	   * @param options - Options for the rejection.
380	   */
381	  reject(
382	    approvalItem: RunToolApprovalItem,
383	    options: { alwaysReject?: boolean } = { alwaysReject: false },
384	  ) {
385	    this._context.rejectTool(approvalItem, options);
386	  }
387	
388	  /**
389	   * Serializes the run state to a JSON object.
390	   *
391	   * This method is used to serialize the run state to a JSON object that can be used to
392	   * resume the run later.
393	   *
394	   * @returns The serialized run state.
395	   */
396	  toJSON(): z.infer<typeof SerializedRunState> {
397	    const output = {
398	      $schemaVersion: CURRENT_SCHEMA_VERSION,
399	      currentTurn: this._currentTurn,
400	      currentAgent: {
401	        name: this._currentAgent.name,
402	      },
403	      originalInput: this._originalInput as any,
404	      modelResponses: this._modelResponses.map((response) => {
405	        return {
406	          usage: {
407	            requests: response.usage.requests,
408	            inputTokens: response.usage.inputTokens,
409	            outputTokens: response.usage.outputTokens,
410	            totalTokens: response.usage.totalTokens,
411	          },
412	          output: response.output as any,
413	          responseId: response.responseId,
414	          providerData: response.providerData,
415	        };
416	      }),
417	      context: this._context.toJSON(),
418	      toolUseTracker: this._toolUseTracker.toJSON(),
419	      maxTurns: this._maxTurns,
420	      currentAgentSpan: this._currentAgentSpan?.toJSON() as any,
421	      noActiveAgentRun: this._noActiveAgentRun,
422	      inputGuardrailResults: this._inputGuardrailResults,
423	      outputGuardrailResults: this._outputGuardrailResults.map((r) => ({
424	        ...r,
425	        agent: r.agent.toJSON(),
426	      })),
427	      currentStep: this._currentStep as any,
428	      lastModelResponse: this._lastTurnResponse as any,
429	      generatedItems: this._generatedItems.map((item) => item.toJSON() as any),
430	      lastProcessedResponse: this._lastProcessedResponse as any,
431	      trace: this._trace ? (this._trace.toJSON() as any) : null,
432	    };
433	
434	    // parsing the schema to ensure the output is valid for reparsing
435	    const parsed = SerializedRunState.safeParse(output);
436	    if (!parsed.success) {
437	      throw new SystemError(
438	        `Failed to serialize run state. ${parsed.error.message}`,
439	      );
440	    }
441	
442	    return parsed.data;
443	  }
444	
445	  /**
446	   * Serializes the run state to a string.
447	   *
448	   * This method is used to serialize the run state to a string that can be used to
449	   * resume the run later.
450	   *
451	   * @returns The serialized run state.
452	   */
453	  toString() {
454	    return JSON.stringify(this.toJSON());
455	  }
456	
457	  /**
458	   * Deserializes a run state from a string.
459	   *
460	   * This method is used to deserialize a run state from a string that was serialized using the
461	   * `toString` method.
462	   */
463	  static async fromString<TContext, TAgent extends Agent<any, any>>(
464	    initialAgent: TAgent,
465	    str: string,
466	  ) {
467	    const [parsingError, jsonResult] = await safeExecute(() => JSON.parse(str));
468	    if (parsingError) {
469	      throw new UserError(
470	        `Failed to parse run state. ${parsingError instanceof Error ? parsingError.message : String(parsingError)}`,
471	      );
472	    }
473	
474	    const currentSchemaVersion = jsonResult.$schemaVersion;
475	    if (!currentSchemaVersion) {
476	      throw new UserError('Run state is missing schema version');
477	    }
478	    if (currentSchemaVersion !== CURRENT_SCHEMA_VERSION) {
479	      throw new UserError(
480	        `Run state schema version ${currentSchemaVersion} is not supported. Please use version ${CURRENT_SCHEMA_VERSION}`,
481	      );
482	    }
483	
484	    const stateJson = SerializedRunState.parse(JSON.parse(str));
485	
486	    const agentMap = buildAgentMap(initialAgent);
487	
488	    //
489	    // Rebuild the context
490	    //
491	    const context = new RunContext<TContext>(
492	      stateJson.context.context as TContext,
493	    );
494	    context._rebuildApprovals(stateJson.context.approvals);
495	
496	    //
497	    // Find the current agent from the initial agent
498	    //
499	    const currentAgent = agentMap.get(stateJson.currentAgent.name);
500	    if (!currentAgent) {
501	      throw new UserError(`Agent ${stateJson.currentAgent.name} not found`);
502	    }
503	
504	    const state = new RunState<TContext, TAgent>(
505	      context,
506	      '',
507	      currentAgent as TAgent,
508	      stateJson.maxTurns,
509	    );
510	    state._currentTurn = stateJson.currentTurn;
511	
512	    // rebuild tool use tracker
513	    state._toolUseTracker = new AgentToolUseTracker();
514	    for (const [agentName, toolNames] of Object.entries(
515	      stateJson.toolUseTracker,
516	    )) {
517	      state._toolUseTracker.addToolUse(
518	        agentMap.get(agentName) as TAgent,
519	        toolNames,
520	      );
521	    }
522	
523	    // rebuild current agent span
524	    if (stateJson.currentAgentSpan) {
525	      if (!stateJson.trace) {
526	        logger.warn('Trace is not set, skipping tracing setup');
527	      }
528	
529	      const trace = getGlobalTraceProvider().createTrace({
530	        traceId: stateJson.trace?.id,
531	        name: stateJson.trace?.workflow_name,
532	        groupId: stateJson.trace?.group_id ?? undefined,
533	        metadata: stateJson.trace?.metadata,
534	      });
535	
536	      state._currentAgentSpan = deserializeSpan(
537	        trace,
538	        stateJson.currentAgentSpan,
539	      );
540	      state._trace = trace;
541	    }
542	    state._noActiveAgentRun = stateJson.noActiveAgentRun;
543	
544	    state._inputGuardrailResults =
545	      stateJson.inputGuardrailResults as InputGuardrailResult[];
546	    state._outputGuardrailResults = stateJson.outputGuardrailResults.map(
547	      (r) => ({
548	        ...r,
549	        agent: agentMap.get(r.agent.name) as Agent<any, any>,
550	      }),
551	    ) as OutputGuardrailResult[];
552	
553	    state._currentStep = stateJson.currentStep;
554	
555	    state._originalInput = stateJson.originalInput;
556	    state._modelResponses = stateJson.modelResponses.map(
557	      deserializeModelResponse,
558	    );
559	    state._lastTurnResponse = stateJson.lastModelResponse
560	      ? deserializeModelResponse(stateJson.lastModelResponse)
561	      : undefined;
562	
563	    state._generatedItems = stateJson.generatedItems.map((item) =>
564	      deserializeItem(item, agentMap),
565	    );
566	    state._lastProcessedResponse = stateJson.lastProcessedResponse
567	      ? await deserializeProcessedResponse(
568	          agentMap,
569	          state._currentAgent,
570	          state._context,
571	          stateJson.lastProcessedResponse,
572	        )
573	      : undefined;
574	
575	    if (stateJson.currentStep?.type === 'next_step_handoff') {
576	      state._currentStep = {
577	        type: 'next_step_handoff',
578	        newAgent: agentMap.get(stateJson.currentStep.newAgent.name) as TAgent,
579	      };
580	    }
581	    return state;
582	  }
583	}
584	
585	/**
586	 * @internal
587	 */
588	export function buildAgentMap(
589	  initialAgent: Agent<any, any>,
590	): Map<string, Agent<any, any>> {
591	  const map = new Map<string, Agent<any, any>>();
592	  const queue: Agent<any, any>[] = [initialAgent];
593	
594	  while (queue.length > 0) {
595	    const currentAgent = queue.shift()!;
596	    if (map.has(currentAgent.name)) {
597	      continue;
598	    }
599	    map.set(currentAgent.name, currentAgent);
600	
601	    for (const handoff of currentAgent.handoffs) {
602	      if (handoff instanceof Agent) {
603	        if (!map.has(handoff.name)) {
604	          queue.push(handoff);
605	        }
606	      } else if (handoff.agent) {
607	        if (!map.has(handoff.agent.name)) {
608	          queue.push(handoff.agent);
609	        }
610	      }
611	    }
612	  }
613	
614	  return map;
615	}
616	
617	/**
618	 * @internal
619	 */
620	export function deserializeSpan(
621	  trace: Trace,
622	  serializedSpan: SerializedSpanType,
623	): Span<any> {
624	  const spanData = serializedSpan.span_data;
625	  const previousSpan = serializedSpan.previous_span
626	    ? deserializeSpan(trace, serializedSpan.previous_span)
627	    : undefined;
628	
629	  const span = getGlobalTraceProvider().createSpan(
630	    {
631	      spanId: serializedSpan.id,
632	      traceId: serializedSpan.trace_id,
633	      parentId: serializedSpan.parent_id ?? undefined,
634	      startedAt: serializedSpan.started_at ?? undefined,
635	      endedAt: serializedSpan.ended_at ?? undefined,
636	      data: spanData as any,
637	    },
638	    trace,
639	  );
640	  span.previousSpan = previousSpan;
641	
642	  return span;
643	}
644	
645	/**
646	 * @internal
647	 */
648	export function deserializeModelResponse(
649	  serializedModelResponse: z.infer<typeof modelResponseSchema>,
650	): ModelResponse {
651	  const usage = new Usage();
652	  usage.requests = serializedModelResponse.usage.requests;
653	  usage.inputTokens = serializedModelResponse.usage.inputTokens;
654	  usage.outputTokens = serializedModelResponse.usage.outputTokens;
655	  usage.totalTokens = serializedModelResponse.usage.totalTokens;
656	
657	  return {
658	    usage,
659	    output: serializedModelResponse.output.map((item) =>
660	      protocol.OutputModelItem.parse(item),
661	    ),
662	    responseId: serializedModelResponse.responseId,
663	    providerData: serializedModelResponse.providerData,
664	  };
665	}
666	
667	/**
668	 * @internal
669	 */
670	export function deserializeItem(
671	  serializedItem: z.infer<typeof itemSchema>,
672	  agentMap: Map<string, Agent<any, any>>,
673	): RunItem {
674	  switch (serializedItem.type) {
675	    case 'message_output_item':
676	      return new RunMessageOutputItem(
677	        serializedItem.rawItem,
678	        agentMap.get(serializedItem.agent.name) as Agent<any, any>,
679	      );
680	    case 'tool_call_item':
681	      return new RunToolCallItem(
682	        serializedItem.rawItem,
683	        agentMap.get(serializedItem.agent.name) as Agent<any, any>,
684	      );
685	    case 'tool_call_output_item':
686	      return new RunToolCallOutputItem(
687	        serializedItem.rawItem,
688	        agentMap.get(serializedItem.agent.name) as Agent<any, any>,
689	        serializedItem.output,
690	      );
691	    case 'reasoning_item':
692	      return new RunReasoningItem(
693	        serializedItem.rawItem,
694	        agentMap.get(serializedItem.agent.name) as Agent<any, any>,
695	      );
696	    case 'handoff_call_item':
697	      return new RunHandoffCallItem(
698	        serializedItem.rawItem,
699	        agentMap.get(serializedItem.agent.name) as Agent<any, any>,
700	      );
701	    case 'handoff_output_item':
702	      return new RunHandoffOutputItem(
703	        serializedItem.rawItem,
704	        agentMap.get(serializedItem.sourceAgent.name) as Agent<any, any>,
705	        agentMap.get(serializedItem.targetAgent.name) as Agent<any, any>,
706	      );
707	    case 'tool_approval_item':
708	      return new RunToolApprovalItem(
709	        serializedItem.rawItem,
710	        agentMap.get(serializedItem.agent.name) as Agent<any, any>,
711	      );
712	  }
713	}
714	
715	/**
716	 * @internal
717	 */
718	async function deserializeProcessedResponse<TContext = UnknownContext>(
719	  agentMap: Map<string, Agent<any, any>>,
720	  currentAgent: Agent<TContext, any>,
721	  context: RunContext<TContext>,
722	  serializedProcessedResponse: z.infer<
723	    typeof serializedProcessedResponseSchema
724	  >,
725	): Promise<ProcessedResponse<TContext>> {
726	  const allTools = await currentAgent.getAllTools(context);
727	  const tools = new Map(
728	    allTools
729	      .filter((tool) => tool.type === 'function')
730	      .map((tool) => [tool.name, tool]),
731	  );
732	  const computerTools = new Map(
733	    allTools
734	      .filter((tool) => tool.type === 'computer')
735	      .map((tool) => [tool.name, tool]),
736	  );
737	  const handoffs = new Map(
738	    currentAgent.handoffs.map((entry) => {
739	      if (entry instanceof Agent) {
740	        return [entry.name, handoff(entry)];
741	      }
742	
743	      return [entry.toolName, entry];
744	    }),
745	  );
746	
747	  const result = {
748	    newItems: serializedProcessedResponse.newItems.map((item) =>
749	      deserializeItem(item, agentMap),
750	    ),
751	    toolsUsed: serializedProcessedResponse.toolsUsed,
752	    handoffs: serializedProcessedResponse.handoffs.map((handoff) => {
753	      if (!handoffs.has(handoff.handoff.toolName)) {
754	        throw new UserError(`Handoff ${handoff.handoff.toolName} not found`);
755	      }
756	
757	      return {
758	        toolCall: handoff.toolCall,
759	        handoff: handoffs.get(handoff.handoff.toolName)!,
760	      };
761	    }),
762	    functions: await Promise.all(
763	      serializedProcessedResponse.functions.map(async (functionCall) => {
764	        if (!tools.has(functionCall.tool.name)) {
765	          throw new UserError(`Tool ${functionCall.tool.name} not found`);
766	        }
767	
768	        return {
769	          toolCall: functionCall.toolCall,
770	          tool: tools.get(functionCall.tool.name)!,
771	        };
772	      }),
773	    ),
774	    computerActions: serializedProcessedResponse.computerActions.map(
775	      (computerAction) => {
776	        const toolName = computerAction.computer.name;
777	        if (!computerTools.has(toolName)) {
778	          throw new UserError(`Computer tool ${toolName} not found`);
779	        }
780	
781	        return {
782	          toolCall: computerAction.toolCall,
783	          computer: computerTools.get(toolName)!,
784	        };
785	      },
786	    ),
787	    mcpApprovalRequests: (
788	      serializedProcessedResponse.mcpApprovalRequests ?? []
789	    ).map((approvalRequest) => ({
790	      requestItem: new RunToolApprovalItem(
791	        approvalRequest.requestItem
792	          .rawItem as unknown as protocol.HostedToolCallItem,
793	        currentAgent,
794	      ),
795	      mcpTool: approvalRequest.mcpTool as unknown as HostedMCPTool,
796	    })),
797	  };
798	
799	  return {
800	    ...result,
801	    hasToolsOrApprovalsToRun(): boolean {
802	      return (
803	        result.handoffs.length > 0 ||
804	        result.functions.length > 0 ||
805	        result.mcpApprovalRequests.length > 0 ||
806	        result.computerActions.length > 0
807	      );
808	    },
809	  };
810	}
