2	import { Trace, TraceOptions } from './traces';
3	import { getGlobalTraceProvider } from './provider';
4	import { Span, SpanError } from './spans';
5	
6	type ContextState = {
7	  trace?: Trace;
8	  span?: Span<any>;
9	  previousSpan?: Span<any>;
10	};
11	
12	let _contextAsyncLocalStorage: AsyncLocalStorage<ContextState> | undefined;
13	
14	function getContextAsyncLocalStorage() {
15	  _contextAsyncLocalStorage ??= new AsyncLocalStorage<ContextState>();
16	  return _contextAsyncLocalStorage;
17	}
18	
19	/**
20	 * This function will get the current trace from the execution context.
21	 *
22	 * @returns The current trace or null if there is no trace.
23	 */
24	export function getCurrentTrace() {
25	  const currentTrace = getContextAsyncLocalStorage().getStore();
26	  if (currentTrace?.trace) {
27	    return currentTrace.trace;
28	  }
29	
30	  return null;
31	}
32	
33	/**
34	 * This function will get the current span from the execution context.
35	 *
36	 * @returns The current span or null if there is no span.
37	 */
38	export function getCurrentSpan() {
39	  const currentSpan = getContextAsyncLocalStorage().getStore();
40	  if (currentSpan?.span) {
41	    return currentSpan.span;
42	  }
43	  return null;
44	}
45	
46	/**
47	 * This is an AsyncLocalStorage instance that stores the current trace.
48	 * It will automatically handle the execution context of different event loop executions.
49	 *
50	 * The functions below should be the only way that this context gets interfaced with.
51	 */
52	function _wrapFunctionWithTraceLifecycle<T>(fn: (trace: Trace) => Promise<T>) {
53	  return async () => {
54	    const trace = getCurrentTrace();
55	    if (!trace) {
56	      throw new Error('No trace found');
57	    }
58	
59	    await trace.start();
60	    const result = await fn(trace);
61	    await trace.end();
62	
63	    return result;
64	  };
65	}
66	
67	/**
68	 * This function will create a new trace and assign it to the execution context of the function
69	 * passed to it.
70	 *
71	 * @param fn - The function to run and assign the trace context to.
72	 * @param options - Options for the creation of the trace
73	 */
74	
75	export async function withTrace<T>(
76	  trace: string | Trace,
77	  fn: (trace: Trace) => Promise<T>,
78	  options: TraceOptions = {},
79	): Promise<T> {
80	  const newTrace =
81	    typeof trace === 'string'
