it('emits agent_end with accumulated usage when the run completes', async () => {
  const usageData = {
    requests: 1,
    inputTokens: 2,
    outputTokens: 3,
    totalTokens: 5,
  };
  const response: ModelResponse = {
    output: [fakeModelMessage('done')],
    usage: new Usage(usageData),
  };
  let finishResponse!: () => void;
  const responseReady = new Promise<void>((resolve) => {
    finishResponse = resolve;
  });

  class SimpleStreamingModel implements Model {
    async getResponse(_req: ModelRequest): Promise<ModelResponse> {
      return response;
    }
    async *getStreamedResponse(): AsyncIterable<StreamEvent> {
      await responseReady;
      yield {
        type: 'response_done',
        response: {
          id: 'r',
          usage: usageData,
          output: response.output,
        },
      } as any;
    }
  }

  const agent = new Agent({
    name: 'Lifecycle',
    model: new SimpleStreamingModel(),
  });
  const runner = new Runner({ tracingDisabled: true });
  const agentEnd = vi.fn();
  const runnerEnd = vi.fn();
  let totalTokensAtAgentEnd: number | undefined;

  const result = await runner.run(agent, 'hi', { stream: true });
  agent.on('agent_end', (context, output) => {
    totalTokensAtAgentEnd = context.usage.totalTokens;
    agentEnd(context, output);
  });
  runner.on('agent_end', runnerEnd);
  finishResponse();
  await result.completed;

  expect(agentEnd).toHaveBeenCalledTimes(1);
  expect(agentEnd).toHaveBeenCalledWith(result.state._context, 'done');
  expect(totalTokensAtAgentEnd).toBe(5);
  expect(runnerEnd).toHaveBeenCalledTimes(1);
  expect(runnerEnd).toHaveBeenCalledWith(
    result.state._context,
    agent,
    'done',
  );
  expect(result.state._context.usage).toMatchObject({
    requests: 1,
    inputTokens: 2,
    outputTokens: 3,
    totalTokens: 5,
  });
});

